import copy
from ta_emss.utilities.trs.err_trs import ErrTrsDeviceRegistration

g_devices_registry = {}  # device_name: device_object


def get_device_registry():
    global g_devices_registry
    return g_devices_registry


def is_registered_device_with_name(device_name):
    return device_name in get_device_registry()


def assert_device_class_provided(device_name, device_params):
    if 'device_class' not in device_params:
        msg = "Can't create device '%s' - no device_class provided" % device_name
        raise ErrTrsDeviceRegistration(msg)


def add_device_to_registry(device_name, device_params, device_object):
    get_device_registry()[device_name] = {'device': device_object,
                                          'dev_params': device_params}


def remove_device_from_registry(device_name):
    if device_name in get_device_registry():
        del get_device_registry()[device_name]


def register_new_device(device_name, device_params):
    device = create_device(device_name, device_params)
    add_device_to_registry(device_name, device_params, device)


def create_device(device_name, device_params):
    copy_of_device_params = copy.deepcopy(device_params)
    dev_class = copy_of_device_params.pop('device_class')
    return dev_class(name=device_name, **copy_of_device_params)


def get_device(name, **dev_params):
    if not is_registered_device_with_name(name):
        assert_device_class_provided(name, dev_params)
        register_new_device(name, dev_params)
    return get_device_registry()[name]['device']
